window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-352c3bd428a4f802"]={"versions": [{"id": "FIG-352c3bd428a4f802", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm, M2-Ebene) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (R21-11).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der sicherheitsbezogenen Brücke (Security Interoperability) zwischen der signalbasierten Classic Platform (<code>SecOC</code> – <em>Secure Onboard Communication</em>) und der serviceorientierten Adaptive Platform (<code>ara::com</code>, <code>ara::crypto</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Verknüpfung von PDU-basierter SecOC-Authentifizierung (<code>SecuredIPdu</code>, <code>SecureCommunicationProps</code>) mit Adaptive-Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) und der Zuordnung zu kryptografischen Schlüssel-Containern (<code>CryptoKeySlot</code>) im Adaptive Crypto Stack.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Classic Platform / PDU- &amp; Signal-Ebene</h5>\n<ul class=\"fig-list\"><li><strong><code>SecuredIPdu</code></strong> <em>(spezialisiert <code>IPdu</code>)</em>:\n<ul class=\"fig-list\"><li>Bildet die kryptografisch geschützte Container-PDU ab.\n</li><li>Aggregation <code>+payload</code> [1]: Verweist auf die zu schützende Nutzdaten-PDU via <code>PduTriggering</code>.\n</li><li>Komposition <code>+secureCommunicationProps</code> [1]: Bindet die SecOC-Metadaten via <code>SecureCommunicationProps</code>.\n</li></ul>\n</li><li><strong><code>SecureCommunicationProps</code></strong>:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger</code>: Eindeutige Kennung des geschützten Datenbereichs / der PDU zur Absicherung gegen Verwechslung/Spoofing.\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>: ID zur Ermittlung des Frischewerts (Freshness Value Manager / FVM) gegen Replay-Angriffe.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Assoziation <code>+iSignalTriggering</code> [0..\\*] <em>(«atpVariation»)</em>: Zuordnung der enthaltenen Signale unter Berücksichtigung von Variantenbildung.\n</li></ul>\n</li><li><strong><code>ISignalTriggering</code></strong> <em>(Identifiable)</em> &amp; <strong><code>ISignal</code></strong> <em>(FibexElement)</em>:\n<ul class=\"fig-list\"><li>Repräsentieren das konkrete Kommunikationssignal und dessen Trigger-Eigenschaften auf dem Bus (0..1-Beziehung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Brückenelement: Service-zu-Signal-Mapping</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceInstanceToSignalMapping</code></strong> <em>(ARElement)</em>:\n<ul class=\"fig-list\"><li>Zentrales Mapping-Element, aggregiert <code>+eventElementMapping</code> [0..\\*] vom Typ <code>SignalBasedEventElementToISignalTriggeringMapping</code>.\n</li><li>Assoziation <code>+serviceInstance</code> [0..1] zu <code>AdaptivePlatformServiceInstance</code>.\n</li></ul>\n</li><li><strong><code>SignalBasedEventElementToISignalTriggeringMapping</code></strong> <em>(spezialisiert <code>AbstractSignalBasedToISignalTriggeringMapping</code>)</em>:\n<ul class=\"fig-list\"><li>Attribut: <code>transmissionTrigger: Boolean [0..1]</code> (definiert, ob das Event/Signal aktiv eine PDU-Übertragung anstößt).\n</li><li>Assoziation <code>+iSignalTriggering</code> [0..1]: Verknüpft das Service-Event mit der Signal-Triggerung der Classic-Welt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Adaptive Platform / Service-Deployment &amp; Security-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(UploadablePackageElement)</em>:\n<ul class=\"fig-list\"><li>Instanz eines Adaptive Services auf einem Deployment-Target.\n</li><li>Komposition <code>+secureComConfig</code> [0..\\*] nach <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+serviceInterfaceDeployment</code> [0..1] nach <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(UploadablePackageElement)</em>:\n<ul class=\"fig-list\"><li>Aggregiert Service-Element-Deployments: <code>+eventDeployment</code> [0..\\<em>] (<code>ServiceEventDeployment</code>) und <code>+fieldDeployment</code> [0..\\</em>] (<code>ServiceFieldDeployment</code>).\n</li></ul>\n</li><li><strong><code>ServiceInterfaceElementSecureComConfig</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration auf Elementebene (Event oder Field-Notifier).\n</li><li>Attribute: <code>dataId: PositiveInteger [0..1]</code>, <code>freshnessValueId: PositiveInteger [0..1]</code>.\n</li><li>Assoziationen: <code>+event</code> [0..1] zu <code>ServiceEventDeployment</code>, <code>+fieldNotifier</code> [0..1] zu <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li><li><strong><code>ComSecOcToCryptoKeySlotMapping</code></strong> <em>(spezialisiert <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>)</em>:\n<ul class=\"fig-list\"><li>Verknüpft die Service-SecOC-Konfiguration (<code>+serviceElementSecureComConfig</code> [0..1]) mit dem konkreten Schlüsselbehälter (<code>+cryptoKeySlot</code> [0..1]).\n</li></ul>\n</li><li><strong><code>CryptoKeySlot</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert den persistierten oder flüchtigen Key-Slot in <code>ara::crypto</code> zur Bereitstellung des symmetrischen Schlüssels (z. B. AES-128 für CMAC).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zwar handelt es sich primär um ein statisches M2-Strukturdiagramm, das Metamodell definiert jedoch die deterministische Laufzeitverarbeitung für gemischte Classic-Adaptive-Netzwerke:</p>\n<ol class=\"fig-list\"><li><strong>Sende- / Serialisierungspfad (Adaptive → Classic):</strong>\n<ul class=\"fig-list\"><li>Ein Service-Event oder Field-Update wird über die <code>AdaptivePlatformServiceInstance</code> emittiert.\n</li><li>Das Framework ermittelt über <code>SignalBasedEventElementToISignalTriggeringMapping</code> die Zielsignale (<code>ISignalTriggering</code>) und verpackt diese in das referenzierte <code>PduTriggering</code>.\n</li><li>Die Laufzeitumgebung liest über <code>ServiceInterfaceElementSecureComConfig</code> <code>dataId</code> und <code>freshnessValueId</code> aus.\n</li><li>Über <code>ComSecOcToCryptoKeySlotMapping</code> wird der zuständige <code>CryptoKeySlot</code> in <code>ara::crypto</code> referenziert, um den Authentication Code (MAC) über Nutzdaten, Data-ID und Freshness Value zu berechnen.\n</li><li>Die erzeugte <code>SecuredIPdu</code> wird mit Nutz-Payload und Authentifizierungsanhang (MAC + ggf. gekürzter Frischewert) auf dem Bus abgesetzt.\n</li></ul>\n</li><li><strong>Empfangs- / Verifikationspfad (Classic → Adaptive):</strong>\n<ul class=\"fig-list\"><li>Eintreffen einer <code>SecuredIPdu</code> am Adaptive-Knoten.\n</li><li>FVM/Crypto-Subsystem ermittelt den vollständigen Freshness-Wert via <code>freshnessValueId</code>.\n</li><li>Schlüsselbezug über <code>CryptoKeySlot</code> via <code>ComSecOcToCryptoKeySlotMapping</code>.\n</li><li>MAC-Verifikation:\n<ul class=\"fig-list\"><li><em>Erfolg:</em> Entpacken der Payload via <code>PduTriggering</code>, Mapping auf Service-Events (<code>ServiceEventDeployment</code>), Weiterleitung an <code>ara::com</code>-Subscriber.\n</li><li><em>Fehlschlag:</em> Verwerfen der PDU, Generierung eines Security-Events / Audit-Log-Eintrags.\n</li></ul>\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest- &amp; Generatorkonsistenz (ARXML Toolchain):</strong>\n<ul class=\"fig-list\"><li>Validierungsregel: Die <code>dataId</code> und <code>freshnessValueId</code> in <code>ServiceInterfaceElementSecureComConfig</code> müssen zwingend konsistent zu den <code>SecureCommunicationProps</code> der Classic <code>SecuredIPdu</code> konfiguriert werden; Diskrepanzen führen zur Unzustellbarkeit von Nachrichten durch MAC-Prüffehler.\n</li></ul>\n</li><li><strong>Schnittstelle zu <code>ara::crypto</code>:</strong>\n<ul class=\"fig-list\"><li>Der referenzierte <code>CryptoKeySlot</code> muss zur Laufzeit über das Adaptive Manifest bezüglich Zugriffsrechten (<code>KeySlotContentAllowedUsage</code>), Algorithmus (z. B. <code>AUTOSAR_CRYPTO_ALG_CMAC_AES</code>) und Schlüsseltyp zum SecOC-Profil des Classic-ECUs passen.\n</li></ul>\n</li><li><strong>Signal-to-Service Bridging:</strong>\n<ul class=\"fig-list\"><li>Ist <code>transmissionTrigger == true</code>, löst die Zuweisung des Werts im Event sofort die PDU-Generierung aus. Bei <code>false</code> erfolgt die Übertragung rein zyklisch über die PDU-Konfiguration.\n</li></ul>\n</li><li><strong>Ressourcen &amp; Performance:</strong>\n<ul class=\"fig-list\"><li>Da Adaptive-Knoten SecOC über den standardisierten Stack abbilden, entfällt proprietäre Konvertierung. Dennoch müssen Latenzzeiten für synchrone/asynchrone Aufrufe zwischen Communication Management (<code>ara::com</code>) und Crypto Stack (<code>ara::crypto</code>) bei zyklischen Hochfrequenz-PDUs im Budget berücksichtigt werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5b2b027d8c85659c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm, M2-Ebene) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (R21-11).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der sicherheitsbezogenen Brücke (Security Interoperability) zwischen der signalbasierten Classic Platform (<code>SecOC</code> – <em>Secure Onboard Communication</em>) und der serviceorientierten Adaptive Platform (<code>ara::com</code>, <code>ara::crypto</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Verknüpfung von PDU-basierter SecOC-Authentifizierung (<code>SecuredIPdu</code>, <code>SecureCommunicationProps</code>) mit Adaptive-Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) und der Zuordnung zu kryptografischen Schlüssel-Containern (<code>CryptoKeySlot</code>) im Adaptive Crypto Stack.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Classic Platform / PDU- &amp; Signal-Ebene</h5>\n<ul class=\"fig-list\"><li><strong><code>SecuredIPdu</code></strong> <em>(spezialisiert <code>IPdu</code>)</em>:\n<ul class=\"fig-list\"><li>Bildet die kryptografisch geschützte Container-PDU ab.\n</li><li>Aggregation <code>+payload</code> [1]: Verweist auf die zu schützende Nutzdaten-PDU via <code>PduTriggering</code>.\n</li><li>Komposition <code>+secureCommunicationProps</code> [1]: Bindet die SecOC-Metadaten via <code>SecureCommunicationProps</code>.\n</li></ul>\n</li><li><strong><code>SecureCommunicationProps</code></strong>:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger</code>: Eindeutige Kennung des geschützten Datenbereichs / der PDU zur Absicherung gegen Verwechslung/Spoofing.\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>: ID zur Ermittlung des Frischewerts (Freshness Value Manager / FVM) gegen Replay-Angriffe.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Assoziation <code>+iSignalTriggering</code> [0..*] <em>(«atpVariation,atpSplitable»)</em>: Zuordnung der enthaltenen Signale unter Berücksichtigung von Variantenbildung und modellübergreifendem Splitting.\n</li></ul>\n</li><li><strong><code>ISignalTriggering</code></strong> <em>(Identifiable)</em> &amp; <strong><code>ISignal</code></strong> <em>(FibexElement)</em>:\n<ul class=\"fig-list\"><li>Repräsentieren das konkrete Kommunikationssignal und dessen Trigger-Eigenschaften auf dem Bus (0..1-Beziehung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Brückenelement: Service-zu-Signal-Mapping</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceInstanceToSignalMapping</code></strong> <em>(ARElement)</em>:\n<ul class=\"fig-list\"><li>Zentrales Mapping-Element, aggregiert <code>+eventElementMapping</code> [0..*] vom Typ <code>SignalBasedEventElementToISignalTriggeringMapping</code>.\n</li><li>Assoziation <code>+serviceInstance</code> [0..1] zu <code>AdaptivePlatformServiceInstance</code>.\n</li></ul>\n</li><li><strong><code>SignalBasedEventElementToISignalTriggeringMapping</code></strong> <em>(spezialisiert <code>AbstractSignalBasedToISignalTriggeringMapping</code>)</em>:\n<ul class=\"fig-list\"><li>Attribut: <code>transmissionTrigger: Boolean [0..1]</code> (definiert, ob das Event/Signal aktiv eine PDU-Übertragung anstößt).\n</li><li>Assoziation <code>+iSignalTriggering</code> [0..1]: Verknüpft das Service-Event mit der Signal-Triggerung der Classic-Welt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Adaptive Platform / Service-Deployment &amp; Security-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(UploadablePackageElement)</em>:\n<ul class=\"fig-list\"><li>Instanz eines Adaptive Services auf einem Deployment-Target.\n</li><li>Komposition <code>+secureComConfig</code> [0..*] nach <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+serviceInterfaceDeployment</code> [0..1] nach <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(UploadablePackageElement)</em>:\n<ul class=\"fig-list\"><li>Aggregiert Service-Element-Deployments: <code>+eventDeployment</code> [0..<em>] (<code>ServiceEventDeployment</code>) und <code>+fieldDeployment</code> [0..</em>] (<code>ServiceFieldDeployment</code>).\n</li></ul>\n</li><li><strong><code>ServiceInterfaceElementSecureComConfig</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration auf Elementebene (Event oder Field-Notifier).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>\n</li><li><code>securedRxVerification: Boolean [0..1]</code>: Steuert empfängerseitig die Notwendigkeit der kryptografischen Verifikation.\n</li></ul>\n</li><li>Assoziationen: <code>+event</code> [0..1] zu <code>ServiceEventDeployment</code>, <code>+fieldNotifier</code> [0..1] zu <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li><li><strong><code>ComSecOcToCryptoKeySlotMapping</code></strong> <em>(FunctionalClusterInteractsWithFunctionalClusterMapping)</em>:\n<ul class=\"fig-list\"><li>Stellt die funktionale Verbindung zwischen der SecOC-Konfiguration und dem Krypto-Stack her.\n</li><li>Assoziation <code>+serviceElementSecureComConfig</code> [0..1] zu <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+cryptoKeySlot</code> [0..1] zu <code>CryptoKeySlot</code>.\n</li></ul>\n</li><li><strong><code>CryptoKeySlot</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert den logischen Krypto-Schlüsselslot in der Adaptive Platform (<code>ara::crypto</code>), der das Schlüsselmaterial für die kryptografische Authentifizierung bzw. Verifikation bereitstellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zwar handelt es sich primär um ein statisches M2-Strukturdiagramm, das Metamodell definiert jedoch die deterministische Laufzeitverarbeitung für gemischte Classic-Adaptive-Netzwerke:</p>\n<ol class=\"fig-list\"><li><strong>Sende- / Serialisierungspfad (Adaptive → Classic):</strong>\n<ul class=\"fig-list\"><li>Ein Service-Event oder Field-Update wird über die <code>AdaptivePlatformServiceInstance</code> emittiert.\n</li><li>Das Framework ermittelt über <code>SignalBasedEventElementToISignalTriggeringMapping</code> die Zielsignale (<code>ISignalTriggering</code>) und verpackt diese in das referenzierte <code>PduTriggering</code>.\n</li><li>Die Laufzeitumgebung liest über <code>ServiceInterfaceElementSecureComConfig</code> <code>dataId</code> und <code>freshnessValueId</code> aus.\n</li><li>Über <code>ComSecOcToCryptoKeySlotMapping</code> wird der zuständige <code>CryptoKeySlot</code> in <code>ara::crypto</code> referenziert, um den Authentication Code (MAC) über Nutzdaten, Data-ID und Freshness Value zu berechnen.\n</li><li>Die erzeugte <code>SecuredIPdu</code> wird mit Nutz-Payload und Authentifizierungsanhang (MAC + ggf. gekürzter Frischewert) auf dem Bus abgesetzt.\n</li></ul>\n</li><li><strong>Empfangs- / Verifikationspfad (Classic → Adaptive):</strong>\n<ul class=\"fig-list\"><li>Eintreffen einer <code>SecuredIPdu</code> am Adaptive-Knoten.\n</li><li>FVM/Crypto-Subsystem ermittelt den vollständigen Freshness-Wert via <code>freshnessValueId</code>.\n</li><li>Schlüsselbezug über <code>CryptoKeySlot</code> via <code>ComSecOcToCryptoKeySlotMapping</code>.\n</li><li>MAC-Verifikation:\n<ul class=\"fig-list\"><li><em>Erfolg:</em> Entpacken der Payload via <code>PduTriggering</code>, Mapping auf Service-Events (<code>ServiceEventDeployment</code>), Weiterleitung an <code>ara::com</code>-Subscriber.\n</li><li><em>Fehlschlag:</em> Verwerfen der PDU, Generierung eines Security-Events / Audit-Log-Eintrags.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektonische Interoperabilität &amp; Empfangsverifikation:</strong>\n<ul class=\"fig-list\"><li>Mit dem neuen Attribut <code>securedRxVerification: Boolean [0..1]</code> in <code>ServiceInterfaceElementSecureComConfig</code> wird konfigurierbar, ob empfängerseitig eine zwingende kryptografische Verifikation durchgeführt werden muss oder übersprungen werden kann.\n</li></ul>\n</li><li><strong>Modell-Splitting und Variantenbildung:</strong>\n<ul class=\"fig-list\"><li>Die Assoziation <code>+iSignalTriggering [0..*]</code> an <code>PduTriggering</code> wurde um den Stereotyp <code>atpSplitable</code> erweitert (<code>«atpVariation,atpSplitable»</code>). Dies erlaubt die Aufteilung von Signalzuordnungen über mehrere ARXML-Dateifragmente bei gleichzeitiger Unterstützung von Modellvarianten.\n</li></ul>\n</li><li><strong>Konsistenzregeln:</strong>\n<ul class=\"fig-list\"><li>Die Aggregationen <code>+payload [1]</code> und <code>+secureCommunicationProps [1]</code> an <code>SecuredIPdu</code> bleiben strikte Pflichtbeziehungen; <code>dataId</code> in <code>SecureCommunicationProps</code> ist unverändert obligatorisch.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eca8d52a22419823", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm, M2-Ebene) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (R21-11).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der sicherheitsbezogenen Brücke (Security Interoperability) zwischen der signalbasierten Classic Platform (<code>SecOC</code> – <em>Secure Onboard Communication</em>) und der serviceorientierten Adaptive Platform (<code>ara::com</code>, <code>ara::crypto</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Verknüpfung von PDU-basierter SecOC-Authentifizierung (<code>SecuredIPdu</code>, <code>SecureCommunicationProps</code>) mit Adaptive-Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) und der Zuordnung zu kryptografischen Schlüssel-Containern (<code>CryptoKeySlot</code>) im Adaptive Crypto Stack.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Classic Platform / PDU- &amp; Signal-Ebene</h5>\n<ul class=\"fig-list\"><li><strong><code>SecuredIPdu</code></strong> <em>(spezialisiert <code>IPdu</code>)</em>:\n<ul class=\"fig-list\"><li>Bildet die kryptografisch geschützte Container-PDU ab.\n</li><li>Aggregation <code>+payload</code> [0..1]: Verweist auf die zu schützende Nutzdaten-PDU via <code>PduTriggering</code> (aufgeweichte Multiplizität).\n</li><li>Komposition <code>+secureCommunicationProps</code> [0..1]: Bindet die SecOC-Metadaten via <code>SecureCommunicationProps</code> (aufgeweichte Multiplizität).\n</li></ul>\n</li><li><strong><code>SecureCommunicationProps</code></strong>:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>: Optionale Kennung des geschützten Datenbereichs / der PDU zur Absicherung gegen Verwechslung/Spoofing.\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>: ID zur Ermittlung des Frischewerts (Freshness Value Manager / FVM) gegen Replay-Angriffe.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Assoziation <code>+iSignalTriggering</code> [0..*] <em>(«atpVariation,atpSplitable»)</em>: Zuordnung der enthaltenen Signale unter Berücksichtigung von Variantenbildung und Splitting.\n</li></ul>\n</li><li><strong><code>ISignalTriggering</code></strong> <em>(Identifiable)</em> &amp; <strong><code>ISignal</code></strong> <em>(«FibexElement», «UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Repräsentieren das konkrete Kommunikationssignal (zusätzlich als Design-Element klassifiziert) und dessen Trigger-Eigenschaften auf dem Bus (0..1-Beziehung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Brückenelement: Service-zu-Signal-Mapping</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceInstanceToSignalMapping</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Zentrales Mapping-Element (auf <code>UploadableDesignElement</code> refaktoriert), aggregiert <code>+eventElementMapping</code> [0..*] vom Typ <code>SignalBasedEventElementToISignalTriggeringMapping</code>.\n</li><li>Assoziation <code>+serviceInstance</code> [0..1] zu <code>AdaptivePlatformServiceInstance</code>.\n</li></ul>\n</li><li><strong><code>SignalBasedEventElementToISignalTriggeringMapping</code></strong> <em>(spezialisiert <code>AbstractSignalBasedToISignalTriggeringMapping</code>)</em>:\n<ul class=\"fig-list\"><li>Attribut: <code>transmissionTrigger: Boolean [0..1]</code> (definiert, ob das Event/Signal aktiv eine PDU-Übertragung anstößt).\n</li><li>Assoziation <code>+iSignalTriggering</code> [0..1]: Verknüpft das Service-Event mit der Signal-Triggerung der Classic-Welt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Adaptive Platform / Service-Deployment &amp; Security-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Instanz eines Adaptive Services auf einem Deployment-Target (auf <code>UploadableDesignElement</code> typisiert).\n</li><li>Komposition <code>+secureComConfig</code> [0..*] nach <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+serviceInterfaceDeployment</code> [0..1] nach <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Aggregiert Service-Element-Deployments unter Unterstützung von Variantenbildung und Splitting:\n<ul class=\"fig-list\"><li>Komposition <code>+eventDeployment</code> [0..*] (<code>«atpVariation,atpSplitable»</code>) nach <code>ServiceEventDeployment</code>.\n</li><li>Komposition <code>+fieldDeployment</code> [0..*] (<code>«atpVariation,atpSplitable»</code>) nach <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ServiceInterfaceElementSecureComConfig</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration auf Elementebene (Event oder Field-Notifier).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>\n</li><li><code>securedRxVerification: Boolean [0..1]</code>\n</li></ul>\n</li><li>Assoziationen: <code>+event</code> [0..1] zu <code>ServiceEventDeployment</code>, <code>+fieldNotifier</code> [0..1] zu <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li><li><strong><code>ComSecOcToCryptoKeySlotMapping</code></strong> <em>(FunctionalClusterInteractsWithFunctionalClusterMapping)</em>:\n<ul class=\"fig-list\"><li>Stellt die funktionale Verbindung zwischen der SecOC-Konfiguration und dem Krypto-Stack her.\n</li><li>Assoziation <code>+serviceElementSecureComConfig</code> [0..1] zu <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+cryptoKeySlot</code> [0..1] zu <code>CryptoKeySlot</code>.\n</li></ul>\n</li><li><strong><code>CryptoKeySlot</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert den logischen Krypto-Schlüsselslot in der Adaptive Platform (<code>ara::crypto</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zwar handelt es sich primär um ein statisches M2-Strukturdiagramm, das Metamodell definiert jedoch die deterministische Laufzeitverarbeitung für gemischte Classic-Adaptive-Netzwerke:</p>\n<ol class=\"fig-list\"><li><strong>Sende- / Serialisierungspfad (Adaptive → Classic):</strong>\n<ul class=\"fig-list\"><li>Ein Service-Event oder Field-Update wird über die <code>AdaptivePlatformServiceInstance</code> emittiert.\n</li><li>Das Framework ermittelt über <code>SignalBasedEventElementToISignalTriggeringMapping</code> die Zielsignale (<code>ISignalTriggering</code>) und verpackt diese in das referenzierte <code>PduTriggering</code>.\n</li><li>Die Laufzeitumgebung liest über <code>ServiceInterfaceElementSecureComConfig</code> <code>dataId</code> und <code>freshnessValueId</code> aus.\n</li><li>Über <code>ComSecOcToCryptoKeySlotMapping</code> wird der zuständige <code>CryptoKeySlot</code> in <code>ara::crypto</code> referenziert, um den Authentication Code (MAC) über Nutzdaten, Data-ID und Freshness Value zu berechnen.\n</li><li>Die erzeugte <code>SecuredIPdu</code> wird mit Nutz-Payload und Authentifizierungsanhang (MAC + ggf. gekürzter Frischewert) auf dem Bus abgesetzt.\n</li></ul>\n</li><li><strong>Empfangs- / Verifikationspfad (Classic → Adaptive):</strong>\n<ul class=\"fig-list\"><li>Eintreffen einer <code>SecuredIPdu</code> am Adaptive-Knoten.\n</li><li>FVM/Crypto-Subsystem ermittelt den vollständigen Freshness-Wert via <code>freshnessValueId</code>.\n</li><li>Schlüsselbezug über <code>CryptoKeySlot</code> via <code>ComSecOcToCryptoKeySlotMapping</code>.\n</li><li>MAC-Verifikation:\n<ul class=\"fig-list\"><li><em>Erfolg:</em> Entpacken der Payload via <code>PduTriggering</code>, Mapping auf Service-Events (<code>ServiceEventDeployment</code>), Weiterleitung an <code>ara::com</code>-Subscriber.\n</li><li><em>Fehlschlag:</em> Verwerfen der PDU, Generierung eines Security-Events / Audit-Log-Eintrags.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Aufweichung der Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>Die Relationen <code>+payload</code> und <code>+secureCommunicationProps</code> an <code>SecuredIPdu</code> sind von <code>1</code> auf <code>[0..1]</code> gelockert worden. Ebenso wurde das Attribut <code>dataId</code> in <code>SecureCommunicationProps</code> von einem Pflichtfeld zu einem optionalen Feld (<code>[0..1]</code>) geändert. Dies gestattet eine schrittweise Modellierung unvollständiger oder rein deklarativer PDU-Spezifikationen im Software-Design.\n</li></ul>\n</li><li><strong>Harmonisierung der Metamodell-Hierarchie:</strong>\n<ul class=\"fig-list\"><li>Die Elemente <code>ServiceInstanceToSignalMapping</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code> und <code>ISignal</code> sind nun als <code>«UploadableDesignElement»</code> (statt <code>«ARElement»</code> bzw. <code>«UploadablePackageElement»</code>) typisiert. Dies vereinheitlicht das Paketierungs- und Ladekonzept auf Entwurfsebene.\n</li></ul>\n</li><li><strong>Erweiterte Splitting-Unterstützung:</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen <code>+eventDeployment</code> und <code>+fieldDeployment</code> an <code>ServiceInterfaceDeployment</code> tragen nun die Stereotypen <code>«atpVariation,atpSplitable»</code>, wodurch Service-Interface-Deployments granular über separate Dateifragmente und Variantenkriterien verteilt werden können.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-59e8cc256ebed6e8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm, M2-Ebene) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (R21-11).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der sicherheitsbezogenen Brücke (Security Interoperability) zwischen der signalbasierten Classic Platform (<code>SecOC</code> – <em>Secure Onboard Communication</em>) und der serviceorientierten Adaptive Platform (<code>ara::com</code>, <code>ara::crypto</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Verknüpfung von PDU-basierter SecOC-Authentifizierung (<code>SecuredIPdu</code>, <code>SecureCommunicationProps</code>) mit Adaptive-Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) und der Zuordnung zu kryptografischen Schlüssel-Containern (<code>CryptoKeySlot</code>) im Adaptive Crypto Stack.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Classic Platform / PDU- &amp; Signal-Ebene</h5>\n<ul class=\"fig-list\"><li><strong><code>SecuredIPdu</code></strong> <em>(spezialisiert <code>IPdu</code>)</em>:\n<ul class=\"fig-list\"><li>Bildet die kryptografisch geschützte Container-PDU ab.\n</li><li>Aggregation <code>+payload</code> [0..1]: Verweist auf die zu schützende Nutzdaten-PDU via <code>PduTriggering</code> (aufgeweichte Multiplizität).\n</li><li>Komposition <code>+secureCommunicationProps</code> [0..1]: Bindet die SecOC-Metadaten via <code>SecureCommunicationProps</code> (aufgeweichte Multiplizität).\n</li></ul>\n</li><li><strong><code>SecureCommunicationProps</code></strong>:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>: Optionale Kennung des geschützten Datenbereichs / der PDU zur Absicherung gegen Verwechslung/Spoofing.\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>: ID zur Ermittlung des Frischewerts (Freshness Value Manager / FVM) gegen Replay-Angriffe.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Assoziation <code>+iSignalTriggering</code> [0..*] <em>(«atpVariation,atpSplitable»)</em>: Zuordnung der enthaltenen Signale unter Berücksichtigung von Variantenbildung und Splitting.\n</li></ul>\n</li><li><strong><code>ISignalTriggering</code></strong> <em>(Identifiable)</em> &amp; <strong><code>ISignal</code></strong> <em>(«FibexElement», «UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Repräsentieren das konkrete Kommunikationssignal (zusätzlich als Design-Element klassifiziert) und dessen Trigger-Eigenschaften auf dem Bus (0..1-Beziehung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Brückenelement: Service-zu-Signal-Mapping</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceInstanceToSignalMapping</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Zentrales Mapping-Element (auf <code>UploadableDesignElement</code> refaktoriert), aggregiert <code>+eventElementMapping</code> [0..*] vom Typ <code>SignalBasedEventElementToISignalTriggeringMapping</code>.\n</li><li>Assoziation <code>+serviceInstance</code> [0..1] zu <code>AdaptivePlatformServiceInstance</code>.\n</li></ul>\n</li><li><strong><code>SignalBasedEventElementToISignalTriggeringMapping</code></strong> <em>(spezialisiert <code>AbstractSignalBasedToISignalTriggeringMapping</code>)</em>:\n<ul class=\"fig-list\"><li>Attribut: <code>transmissionTrigger: Boolean [0..1]</code> (definiert, ob das Event/Signal aktiv eine PDU-Übertragung anstößt).\n</li><li>Assoziation <code>+iSignalTriggering</code> [0..1]: Verknüpft das Service-Event mit der Signal-Triggerung der Classic-Welt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Adaptive Platform / Service-Deployment &amp; Security-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Instanz eines Adaptive Services auf einem Deployment-Target (auf <code>UploadableDesignElement</code> typisiert).\n</li><li>Komposition <code>+secureComConfig</code> [0..*] nach <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+serviceInterfaceDeployment</code> [0..1] nach <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Aggregiert Service-Element-Deployments unter Unterstützung von Variantenbildung und Splitting:\n<ul class=\"fig-list\"><li>Komposition <code>+eventDeployment</code> [0..*] (<code>«atpVariation,atpSplitable»</code>) nach <code>ServiceEventDeployment</code>.\n</li><li>Komposition <code>+fieldDeployment</code> [0..*] (<code>«atpVariation,atpSplitable»</code>) nach <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ServiceInterfaceElementSecureComConfig</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration auf Elementebene (Event oder Field-Notifier).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>\n</li><li><code>securedRxVerification: Boolean [0..1]</code>\n</li></ul>\n</li><li>Assoziationen: <code>+event</code> [0..1] zu <code>ServiceEventDeployment</code>, <code>+fieldNotifier</code> [0..1] zu <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li><li><strong><code>ComSecOcToCryptoKeySlotMapping</code></strong> <em>(FunctionalClusterInteractsWithFunctionalClusterMapping)</em>:\n<ul class=\"fig-list\"><li>Stellt die funktionale Verbindung zwischen der SecOC-Konfiguration und dem Krypto-Stack her.\n</li><li>Assoziation <code>+serviceElementSecureComConfig</code> [0..1] zu <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+cryptoKeySlot</code> [0..1] zu <code>CryptoKeySlot</code>.\n</li></ul>\n</li><li><strong><code>CryptoKeySlot</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert den logischen Krypto-Schlüsselslot in der Adaptive Platform (<code>ara::crypto</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zwar handelt es sich primär um ein statisches M2-Strukturdiagramm, das Metamodell definiert jedoch die deterministische Laufzeitverarbeitung für gemischte Classic-Adaptive-Netzwerke:</p>\n<ol class=\"fig-list\"><li><strong>Sende- / Serialisierungspfad (Adaptive → Classic):</strong>\n<ul class=\"fig-list\"><li>Ein Service-Event oder Field-Update wird über die <code>AdaptivePlatformServiceInstance</code> emittiert.\n</li><li>Das Framework ermittelt über <code>SignalBasedEventElementToISignalTriggeringMapping</code> die Zielsignale (<code>ISignalTriggering</code>) und verpackt diese in das referenzierte <code>PduTriggering</code>.\n</li><li>Die Laufzeitumgebung liest über <code>ServiceInterfaceElementSecureComConfig</code> <code>dataId</code> und <code>freshnessValueId</code> aus.\n</li><li>Über <code>ComSecOcToCryptoKeySlotMapping</code> wird der zuständige <code>CryptoKeySlot</code> in <code>ara::crypto</code> referenziert, um den Authentication Code (MAC) über Nutzdaten, Data-ID und Freshness Value zu berechnen.\n</li><li>Die erzeugte <code>SecuredIPdu</code> wird mit Nutz-Payload und Authentifizierungsanhang (MAC + ggf. gekürzter Frischewert) auf dem Bus abgesetzt.\n</li></ul>\n</li><li><strong>Empfangs- / Verifikationspfad (Classic → Adaptive):</strong>\n<ul class=\"fig-list\"><li>Eintreffen einer <code>SecuredIPdu</code> am Adaptive-Knoten.\n</li><li>FVM/Crypto-Subsystem ermittelt den vollständigen Freshness-Wert via <code>freshnessValueId</code>.\n</li><li>Schlüsselbezug über <code>CryptoKeySlot</code> via <code>ComSecOcToCryptoKeySlotMapping</code>.\n</li><li>MAC-Verifikation:\n<ul class=\"fig-list\"><li><em>Erfolg:</em> Entpacken der Payload via <code>PduTriggering</code>, Mapping auf Service-Events (<code>ServiceEventDeployment</code>), Weiterleitung an <code>ara::com</code>-Subscriber.\n</li><li><em>Fehlschlag:</em> Verwerfen der PDU, Generierung eines Security-Events / Audit-Log-Eintrags.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Aufweichung der Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>Die Relationen <code>+payload</code> und <code>+secureCommunicationProps</code> an <code>SecuredIPdu</code> sind von <code>1</code> auf <code>[0..1]</code> gelockert worden. Ebenso wurde das Attribut <code>dataId</code> in <code>SecureCommunicationProps</code> von einem Pflichtfeld zu einem optionalen Feld (<code>[0..1]</code>) geändert. Dies gestattet eine schrittweise Modellierung unvollständiger oder rein deklarativer PDU-Spezifikationen im Software-Design.\n</li></ul>\n</li><li><strong>Harmonisierung der Metamodell-Hierarchie:</strong>\n<ul class=\"fig-list\"><li>Die Elemente <code>ServiceInstanceToSignalMapping</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code> und <code>ISignal</code> sind nun als <code>«UploadableDesignElement»</code> (statt <code>«ARElement»</code> bzw. <code>«UploadablePackageElement»</code>) typisiert. Dies vereinheitlicht das Paketierungs- und Ladekonzept auf Entwurfsebene.\n</li></ul>\n</li><li><strong>Erweiterte Splitting-Unterstützung:</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen <code>+eventDeployment</code> und <code>+fieldDeployment</code> an <code>ServiceInterfaceDeployment</code> tragen nun die Stereotypen <code>«atpVariation,atpSplitable»</code>, wodurch Service-Interface-Deployments granular über separate Dateifragmente und Variantenkriterien verteilt werden können.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2576aad8e2c7c869", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm, M2-Ebene) gemäß <code>AUTOSAR_TPS_ManifestSpecification</code> (R21-11).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der sicherheitsbezogenen Brücke (Security Interoperability) zwischen der signalbasierten Classic Platform (<code>SecOC</code> – <em>Secure Onboard Communication</em>) und der serviceorientierten Adaptive Platform (<code>ara::com</code>, <code>ara::crypto</code>).\n</li><li><strong>Funktionale Einordnung:</strong> Verknüpfung von PDU-basierter SecOC-Authentifizierung (<code>SecuredIPdu</code>, <code>SecureCommunicationProps</code>) mit Adaptive-Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) und der Zuordnung zu kryptografischen Schlüssel-Containern (<code>CryptoKeySlot</code>) im Adaptive Crypto Stack.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Classic Platform / PDU- &amp; Signal-Ebene</h5>\n<ul class=\"fig-list\"><li><strong><code>SecuredIPdu</code></strong> <em>(spezialisiert <code>IPdu</code>)</em>:\n<ul class=\"fig-list\"><li>Bildet die kryptografisch geschützte Container-PDU ab.\n</li><li>Aggregation <code>+payload</code> [0..1]: Verweist auf die zu schützende Nutzdaten-PDU via <code>PduTriggering</code>.\n</li><li>Komposition <code>+secureCommunicationProps</code> [0..1]: Bindet die SecOC-Metadaten via <code>SecureCommunicationProps</code>.\n</li></ul>\n</li><li><strong><code>SecureCommunicationProps</code></strong>:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>: Optionale Kennung des geschützten Datenbereichs / der PDU zur Absicherung gegen Verwechslung/Spoofing.\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>: ID zur Ermittlung des Frischewerts (Freshness Value Manager / FVM) gegen Replay-Angriffe.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Assoziation <code>+iSignalTriggering</code> [0..*] <em>(«atpVariation,atpSplitable»)</em>: Zuordnung der enthaltenen Signale unter Berücksichtigung von Variantenbildung und Splitting.\n</li></ul>\n</li><li><strong><code>ISignalTriggering</code></strong> <em>(Identifiable)</em> &amp; <strong><code>ISignal</code></strong> <em>(«FibexElement», «UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Repräsentieren das konkrete Kommunikationssignal und dessen Trigger-Eigenschaften auf dem Bus (0..1-Beziehung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Brückenelement: Service-zu-Signal-Mapping</h5>\n<ul class=\"fig-list\"><li><strong><code>ServiceInstanceToSignalMapping</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Zentrales Mapping-Element, aggregiert <code>+eventElementMapping</code> [0..*] vom Typ <code>SignalBasedEventElementToISignalTriggeringMapping</code>.\n</li><li>Assoziation <code>+serviceInstance</code> [0..1] zu <code>AdaptivePlatformServiceInstance</code>.\n</li></ul>\n</li><li><strong><code>SignalBasedEventElementToISignalTriggeringMapping</code></strong> <em>(spezialisiert <code>AbstractSignalBasedToISignalTriggeringMapping</code>)</em>:\n<ul class=\"fig-list\"><li>Attribut: <code>transmissionTrigger: Boolean [0..1]</code> (definiert, ob das Event/Signal aktiv eine PDU-Übertragung anstößt).\n</li><li>Assoziation <code>+iSignalTriggering</code> [0..1]: Verknüpft das Service-Event mit der Signal-Triggerung der Classic-Welt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Adaptive Platform / Service-Deployment &amp; Security-Konfiguration</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Instanz eines Adaptive Services auf einem Deployment-Target.\n</li><li>Komposition <code>+secureComConfig</code> [0..*] nach <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+serviceInterfaceDeployment</code> [0..1] nach <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li><li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(«UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Aggregiert Service-Element-Deployments unter Unterstützung von Variantenbildung und Splitting:\n<ul class=\"fig-list\"><li>Komposition <code>+eventDeployment</code> [0..*] (<code>«atpVariation,atpSplitable»</code>) nach <code>ServiceEventDeployment</code>.\n</li><li>Komposition <code>+fieldDeployment</code> [0..*] (<code>«atpVariation,atpSplitable»</code>) nach <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ServiceEventDeployment</code></strong> <em>(«ServiceInterfaceDeploymentElement»)</em>:\n<ul class=\"fig-list\"><li>Deployment-Spezifikation für Service-Events (generalisiert von <code>ServiceInterfaceDeploymentElement</code>).\n</li></ul>\n</li><li><strong><code>ServiceFieldDeployment</code></strong> <em>(«ServiceInterfaceDeploymentElement»)</em>:\n<ul class=\"fig-list\"><li>Deployment-Spezifikation für Service-Fields (generalisiert von <code>ServiceInterfaceDeploymentElement</code>).\n</li></ul>\n</li><li><strong><code>ServiceInterfaceElementSecureComConfig</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Sicherheitskonfiguration auf Elementebene (Event oder Field-Notifier).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>dataId: PositiveInteger [0..1]</code>\n</li><li><code>freshnessValueId: PositiveInteger [0..1]</code>\n</li><li><code>securedRxVerification: Boolean [0..1]</code>\n</li></ul>\n</li><li>Assoziationen: <code>+event</code> [0..1] zu <code>ServiceEventDeployment</code>, <code>+fieldNotifier</code> [0..1] zu <code>ServiceFieldDeployment</code>.\n</li></ul>\n</li><li><strong><code>ComSecOcToCryptoKeySlotMapping</code></strong> <em>(FunctionalClusterInteractsWithFunctionalClusterMapping)</em>:\n<ul class=\"fig-list\"><li>Stellt die funktionale Verbindung zwischen der SecOC-Konfiguration und dem Krypto-Stack her.\n</li><li>Assoziation <code>+serviceElementSecureComConfig</code> [0..1] zu <code>ServiceInterfaceElementSecureComConfig</code>.\n</li><li>Assoziation <code>+cryptoKeySlot</code> [0..1] zu <code>CryptoKeySlot</code>.\n</li></ul>\n</li><li><strong><code>CryptoKeySlot</code></strong> <em>(Identifiable)</em>:\n<ul class=\"fig-list\"><li>Repräsentiert den logischen Krypto-Schlüsselslot in der Adaptive Platform (<code>ara::crypto</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zwar handelt es sich primär um ein statisches M2-Strukturdiagramm, das Metamodell definiert jedoch die deterministische Laufzeitverarbeitung für gemischte Classic-Adaptive-Netzwerke:</p>\n<ol class=\"fig-list\"><li><strong>Sende- / Serialisierungspfad (Adaptive → Classic):</strong>\n<ul class=\"fig-list\"><li>Ein Service-Event oder Field-Update wird über die <code>AdaptivePlatformServiceInstance</code> emittiert.\n</li><li>Das Framework ermittelt über <code>SignalBasedEventElementToISignalTriggeringMapping</code> die Zielsignale (<code>ISignalTriggering</code>) und verpackt diese in das referenzierte <code>PduTriggering</code>.\n</li><li>Die Laufzeitumgebung liest über <code>ServiceInterfaceElementSecureComConfig</code> <code>dataId</code> und <code>freshnessValueId</code> aus.\n</li><li>Über <code>ComSecOcToCryptoKeySlotMapping</code> wird der zuständige <code>CryptoKeySlot</code> in <code>ara::crypto</code> referenziert, um den Authentication Code (MAC) über Nutzdaten, Data-ID und Freshness Value zu berechnen.\n</li><li>Die erzeugte <code>SecuredIPdu</code> wird mit Nutz-Payload und Authentifizierungsanhang (MAC + ggf. gekürzter Frischewert) auf dem Bus abgesetzt.\n</li></ul>\n</li><li><strong>Empfangs- / Verifikationspfad (Classic → Adaptive):</strong>\n<ul class=\"fig-list\"><li>Eintreffen einer <code>SecuredIPdu</code> am Adaptive-Knoten.\n</li><li>FVM/Crypto-Subsystem ermittelt den vollständigen Freshness-Wert via <code>freshnessValueId</code>.\n</li><li>Schlüsselbezug über <code>CryptoKeySlot</code> via <code>ComSecOcToCryptoKeySlotMapping</code>.\n</li><li>MAC-Verifikation:\n<ul class=\"fig-list\"><li><em>Erfolg:</em> Entpacken der Payload via <code>PduTriggering</code>, Mapping auf Service-Events (<code>ServiceEventDeployment</code>), Weiterleitung an <code>ara::com</code>-Subscriber.\n</li><li><em>Fehlschlag:</em> Verwerfen der PDU, Generierung eines Security-Events / Audit-Log-Eintrags.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Einführung der Metaklasse <code>ServiceInterfaceDeploymentElement</code>:</strong>\n<ul class=\"fig-list\"><li><code>ServiceEventDeployment</code> und <code>ServiceFieldDeployment</code> sind nun über <code>«ServiceInterfaceDeploymentElement»</code> anstelle von unmittelbar <code>«Identifiable»</code> typisiert. Dies standardisiert die gemeinsame Metamodell-Basis für alle untergeordneten Deployment-Elemente innerhalb eines <code>ServiceInterfaceDeployment</code>.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-352c3bd428a4f802", "to": "FIG-5b2b027d8c85659c", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ServiceInterfaceElementSecureComConfig</code>: Neues Attribut <code>+ securedRxVerification: Boolean [0..1]</code> ergänzt.\n</li><li><code>PduTriggering</code>: Assoziation <code>+iSignalTriggering</code> von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li><li><code>PduTriggering</code> / <code>SecuredIPdu</code>: Positionierung im oberen Diagrammbereich horizontal neu arrangiert.\n</li><li><code>ComSecOcToCryptoKeySlotMapping</code> / <code>CryptoKeySlot</code>: Im Diagrammlayout an die linke Seite verlegt.\n</li></ul>"}, {"from": "FIG-5b2b027d8c85659c", "to": "FIG-eca8d52a22419823", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SecuredIPdu</code>: Multiplizität der Aggregation <code>+payload</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><code>SecuredIPdu</code>: Multiplizität der Komposition <code>+secureCommunicationProps</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><code>SecureCommunicationProps</code>: Multiplizität des Attributs <code>dataId</code> von <code>PositiveInteger</code> (1) auf <code>PositiveInteger [0..1]</code> geändert.\n</li><li><code>ISignal</code>: Zusätzlich als <code>«UploadableDesignElement»</code> typisiert (neben <code>«FibexElement»</code>).\n</li><li><code>ServiceInstanceToSignalMapping</code>: Stereotyp von <code>«ARElement»</code> auf <code>«UploadableDesignElement»</code> geändert.\n</li><li><code>AdaptivePlatformServiceInstance</code>: Stereotyp von <code>«UploadablePackageElement»</code> auf <code>«UploadableDesignElement»</code> geändert.\n</li><li><code>ServiceInterfaceDeployment</code>: Stereotyp von <code>«UploadablePackageElement»</code> auf <code>«UploadableDesignElement»</code> geändert.\n</li><li><code>ServiceInterfaceDeployment</code>: Kompositionen <code>+eventDeployment 0..*</code> und <code>+fieldDeployment 0..*</code> um den Stereotyp <code>«atpVariation,atpSplitable»</code> erweitert.\n</li></ul>"}, {"from": "FIG-eca8d52a22419823", "to": "FIG-59e8cc256ebed6e8", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-59e8cc256ebed6e8", "to": "FIG-2576aad8e2c7c869", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ServiceEventDeployment</code>: Metaklassen-Klassifikation von <code>«Identifiable»</code> auf <code>«ServiceInterfaceDeploymentElement»</code> geändert.\n</li><li><code>ServiceFieldDeployment</code>: Metaklassen-Klassifikation von <code>«Identifiable»</code> auf <code>«ServiceInterfaceDeploymentElement»</code> geändert.\n</li></ul>"}]};
